import itertools
# use test rows and quadrants
panels={(r,c):[row[c*6:c*6+5] for row in rows[r*6:r*6+5]] for r in range(2) for c in range(2)}
labels={(0,0):'TL',(0,1):'TR',(1,0):'BL',(1,1):'BR'}
def shifted(m,d):
    z=[[7]*5 for _ in range(5)]
    for r in range(5):
        for c in range(5):
            if m[r][c]!=7:
                z[r][c+d]=m[r][c]
    return z
opts={}
for pos,m in panels.items():
    minc=min(c for row in m for c,v in enumerate(row) if v!=7); maxc=max(c for row in m for c,v in enumerate(row) if v!=7)
    opts[pos]=[]
    for d in range(-minc,4-maxc+1):
        z=shifted(m,d)
        opts[pos].append((d,z,sigs(z)))
    print(labels[pos], minc,maxc,[(d,s['left'],s['right']) for d,z,s in opts[pos]])
solutions=[]
for perm in itertools.permutations(panels):
    if any(not all(v==0 for v in opts[perm[0]][k][2]['left']) for k in []): pass
    # select shifts recursively
    for combo in itertools.product(*[opts[p] for p in perm]):
        if any(any(x) for x in combo[0][2]['left']): continue
        if any(x for x in combo[-1][2]['right']): continue
        if all(combo[i][2]['right']==combo[i+1][2]['left'] for i in range(3)):
            solutions.append((tuple(labels[p] for p in perm),tuple(x[0] for x in combo)))
print('solutions',solutions[:20], 'count',len(solutions))

